window.addEventListener('DOMContentLoaded',()=>{'use strict';
const $=id=>document.getElementById(id),A=GlyphProgram,F=GlyphFlow,stage=$('math-stage'),flow=$('logic-stage'),node=$('sculpture');let selection='harmonic',running=false;
const number={type:'number',minimum:0,maximum:.65};
function controllerDefinition(){return {interface:new F.ComponentInterface({state:{type:'object',properties:{amplitude:number},required:['amplitude'],additionalProperties:false},methods:{sculpt:{input:number,output:number,interaction:{travel:'hop',receive:'pixel-sort',duration:.7},handle:(state,value)=>({state:{...state,amplitude:value},result:value})}}}),initial:{amplitude:.22},organize:(state,{width,height})=>Array.from({length:20},(_,i)=>{const a=i/20*A.math.TAU,r=55+state.amplitude*75;return {id:'sample-'+i,label:['POINT','TANGENT','NORMAL','STATE','CONTRACT'][i%5],x:width/2+r*Math.cos(a),y:height*.56+r*.55*Math.sin(a),z:r*.6*Math.sin(a),color:i%5?'#638c81':'#86d6ee'};}),motion:{type:'custom',duration:1.8,sample:(from,to,{progress:t,seed})=>{const ease=t*t*(3-2*t),arc=Math.sin(Math.PI*t)*(seed%2?1:-1)*36;return {x:from.x+(to.x-from.x)*ease+arc,y:from.y+(to.y-from.y)*ease,z:(from.z||0)+((to.z||0)-(from.z||0))*ease+Math.sin(A.math.TAU*t)*24};}}};}
node.definition=controllerDefinition();
function build(){stage.program=GlyphMathExamples.make(selection,node.value);$('code').textContent=(selection==='harmonic'?GlyphMathExamples.harmonicShell:selection==='knot'?GlyphMathExamples.torusKnot:GlyphMathExamples.ribbonSurface).toString()+'\n\n'+GlyphMathExamples.make.toString();$('logic-code').textContent=controllerDefinition.toString();$('attached').parentElement.hidden=selection!=='harmonic';}
node.addEventListener('glyph-state',()=>{if(stage.program)stage.params=node.value;$('state').textContent=JSON.stringify(node.value,null,2);});
$('example').onchange=()=>{selection=$('example').value;build();};$('pause').onclick=()=>{const paused=stage.toggleAttribute('paused');$('pause').textContent=paused?'Play':'Pause';};$('audit').onclick=()=>{try{const a=stage.program.audit({frames:16});$('stats').textContent=a.points+' POINTS / '+a.frames+' FINITE SAMPLE FRAMES / RADIUS '+a.maxRadius.toFixed(3)+' · NO PROOF CLAIM';}catch(e){$('error').textContent=e.message;}};
$('apply-amplitude').onclick=async()=>{if(running)return;running=true;$('apply-amplitude').disabled=true;try{const value=Number($('amplitude').value),r=flow.getBoundingClientRect();$('logic-status').textContent='Sending '+value.toFixed(2)+' to sculpture.sculpt…';const receipt=await flow.invoke({to:'sculpture',method:'sculpt',payload:value,origin:{x:-20,y:r.height/2}});$('logic-status').textContent='Accepted '+receipt.result.toFixed(2)+' · typed result';}catch(e){$('logic-status').textContent=e.message;}finally{running=false;$('apply-amplitude').disabled=false;}};
$('amplitude').oninput=()=>{$('amplitude-label').textContent=Number($('amplitude').value).toFixed(2);};$('attached').onclick=()=>{$('logic-status').textContent='Native HTML button attached to the exact authored surface point.';};stage.addEventListener('glyph-ready',e=>{$('stats').textContent=e.detail.instances+' INSTANCES / '+e.detail.drawCalls+' DRAWS / '+e.detail.renderer.toUpperCase()+' / FUNCTION GEOMETRY';});stage.addEventListener('glyph-error',e=>$('error').textContent=e.detail.message);flow.addEventListener('glyph-flow-error',e=>$('error').textContent=e.detail.message);build();$('state').textContent=JSON.stringify(node.value,null,2);
});
